import os, time, hashlib
from cryptography.hazmat.primitives import hashes

def time_hash(data, rounds=10):
    t=time.time();
    for i in range(rounds):
        d = hashes.Hash(hashes.SHA256())
        d.update(data)
        d.finalize()
    return time.time()-t

def time_hashlib(data, rounds=10):
    t=time.time();
    for i in range(rounds):
        hashlib.sha256(data).digest()
    return time.time()-t
for size in [1024, 8192, 65536, 1048576, 20971520]:
    data=os.urandom(size)
    ct=time_hash(data, 3)
    ht=time_hashlib(data,3)
    print(size, ct, ht)
